      const [, start, end, total] =
        text.match(/^SHOWING\s+(\d+)-(\d+)\s+OF\s+(\d+)\s+TALENTS$/i) || [];
      return locale === "en"
        ? `SHOWING ${start}-${end} OF ${total} TALENTS`
        : `MENAMPILKAN ${start}-${end} DARI ${total} TALENTA`;
